/* Continuous temporary service. Schematic proximity is not GPS distance. */
let radarRunning=true,radarStarted=Date.now(),radarBase=localMinutes(new Date().toISOString());
arrivalMode='preview';arrivalTime=radarBase;arrivalDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function demoFleet(route,direction){let ids=arrivals.stopOrder(route,direction),board=Math.max(0,ids.indexOf(arrivalBoard)),probe=arrivals.preview(route,{date:arrivalDate,time:arrivalTime,direction,rain:arrivalRain,corridor:arrivalCorridor,headway:40});let offset=probe.stops[board].offset;let anchor=Math.floor((arrivalTime-offset)/40)*40-80;return arrivals.preview(route,{date:arrivalDate,time:arrivalTime,anchor,direction,rain:arrivalRain,corridor:arrivalCorridor,headway:40,count:7}).vehicles.map((v,i)=>({...v,number:route.id.slice(2)+(direction===1?'A':'B')+String(Math.round(v.start/40)),crowding:['Seats available','Standing room','Crowded'][i%3]}))}
const radarModelBase=arrivalModel;
arrivalModel=function(){let m=radarModelBase();if(arrivalMode!=='preview')return m;m.vehicles=demoFleet(m.route,arrivalDirection);m.bus=m.vehicles.find(v=>v.number===arrivalBus)||m.vehicles.find(v=>atBoard(v,m)?.expectedDeparture>=m.now)||m.vehicles[0];m.preview.context.headway=40;return m};
modeBadge=function(){return `<span class="arrival-data-badge preview-mode">${arrivalMode==='preview'?'MOVING DEMO · 40 MIN':'OPERATOR DATA'}</span>`};
function crowdChip(v){let n=v.crowding==='Seats available'?1:v.crowding==='Standing room'?2:v.crowding==='Crowded'?3:0;return `<span class="signal crowd-${n}" title="${safe(v.crowding)}" aria-label="${safe(v.crowding)}">${Array.from({length:n||1},()=>`<svg viewBox="0 0 12 22" aria-hidden="true"><circle cx="6" cy="4" r="2.5"/><path d="M3 21v-7H1V8h10v6H9v7H6v-7H5v7Z"/></svg>`).join('')}<small>${n===1?'Low':n===2?'Medium':n===3?'High':'Unknown'}</small></span>`}
function timingChip(t,m){let passed=t.expectedDeparture<m.now,late=Math.round(t.expectedArrival-t.scheduledArrival);return `<span class="signal ${passed?'passed':late>0?'late':'ontime'}">${ic(passed?'check':'clock')}<b>${passed?'Passed':m.now>=t.expectedArrival?'At stop':Math.ceil(t.expectedArrival-m.now)+' min'}</b></span>${!passed&&late>0?`<span class="signal late">${ic('clock')}+${late}m</span>`:''}`}
function radarCard(){let m=arrivalModel();return `<section class="section radar-card"><div class="sectionhead between"><h2>Bus radar</h2><button class="textbtn" onclick="openNetworkMap()">Expand map ↗</button></div><div class="radar-search"><button onclick="planJourney()">${ic('search')}Where to?</button><button onclick="openArrivalRoutePicker()">${routeTag(arrivalRoute)} Change</button></div><div class="radar-summary"><span class="radar-pulse"></span><b>Every 40 min · both directions</b><button onclick="radarRunning=!radarRunning;render()">${radarRunning?'Pause':'Resume'}</button></div><p class="tiny">Temporary demo · proximity to your selected boarding stop</p><button class="radar-map-preview" onclick="openNetworkMap()" aria-label="Expand interactive bus radar">${networkSvg(false)}<span>Open interactive map ↗</span></button><div class="radar-legend">${crowdChip({crowding:'Seats available'})}${crowdChip({crowding:'Standing room'})}${crowdChip({crowding:'Crowded'})}</div></section>`}
upcomingBusCards=function(){let m=arrivalModel();if(arrivalMode!=='preview')return '<section class="section"><button class="primary full" onclick="setArrivalMode(\'preview\')">Use moving demo service</button></section>';let all=m.vehicles.map(v=>({v,t:atBoard(v,m)})).filter(x=>x.t),past=all.filter(x=>x.t.expectedDeparture<m.now).at(-1),next=all.filter(x=>x.t.expectedDeparture>=m.now&&x.t.expectedArrival<=m.now+40),rows=[...(past?[past]:[]),...next];return `<section class="section"><div class="sectionhead between"><h2>Your 40-minute window</h2><span class="tiny">${etaClock(m.now)} – ${etaClock(m.now+40)}</span></div>${rows.map(({v,t})=>`<button class="radar-bus-row" style="--bus-color:${m.route.color}" onclick="openArrivalBus('${v.number}')"><span class="radar-route-icon">${ic('bus')}<b>${m.route.id}</b></span><span class="radar-bus-detail"><b>Towards ${safe(stopName(m.ids.at(-1)))}</b><span>${timingChip(t,m)}</span><small>${etaClock(t.expectedArrival)} arrival · ${etaClock(t.expectedDeparture)} departure</small></span>${crowdChip(v)}</button>`).join('')}<button class="secondary full" onclick="switchArrivalDirection()">⇄ See buses towards ${safe(stopName(m.ids[0]))}</button></section>`};
const radarHeroBase=arrivalHero;arrivalHero=function(){return radarHeroBase().replace(/Bus #.*? · expected /,'Expected ').replace(/<b>#.*?<\/b>/,`<b>${arrivalRoute}</b>`)};
const radarHomeBase=home;home=function(){let html=radarHomeBase();return html.replace(arrivalControls(),arrivalControls()+radarCard())};
// All seven lines carry vehicles in both directions, using source geometry only.
busMapMarkers=function(){if(arrivalMode!=='preview')return '';return network.data.routes.filter(r=>networkRoute==='all'||r.id===networkRoute).flatMap(r=>[1,-1].flatMap(direction=>demoFleet(r,direction).filter(v=>['between','at-stop'].includes(v.position.phase)).map(v=>{let p=arrivals.pointOnRoute(r,direction,v.position.index,v.position.fraction);return `<g class="telemetry-marker" transform="translate(${p[0]} ${p[1]})" data-marker-x="${p[0]}" data-marker-y="${p[1]}" role="button" tabindex="0" aria-label="${r.id} bus towards ${safe(stopName(arrivals.stopOrder(r,direction).at(-1)))}" onclick="event.stopPropagation();openRadarBus('${r.id}',${direction},'${v.number}')" onkeydown="if(event.key==='Enter')openRadarBus('${r.id}',${direction},'${v.number}')"><title>${r.id} · ${direction===1?'Outbound':'Inbound'} · demo</title><rect x="-28" y="-40" width="56" height="20" rx="6" fill="${r.color}" stroke="white"/><text x="0" y="-26" text-anchor="middle" fill="${r.id==='CM02'?'#111':'white'}" font-size="10" font-weight="700">${r.id} ${direction===1?'→':'←'}</text><path d="M0 -20V-11" stroke="${r.color}" stroke-width="2"/><circle r="13" fill="${r.color}" stroke="white" stroke-width="3"/><use href="#i-bus" x="-8" y="-8" width="16" height="16" stroke="${r.id==='CM02'?'#111':'white'}" fill="none" stroke-width="1.7"/></g>`}))).join('')};
function openRadarBus(route,direction,number){arrivalRoute=route;arrivalDirection=direction;openArrivalBus(number)}
const radarOpenMapBase=openNetworkMap;openNetworkMap=function(){radarOpenMapBase();$('.sheet')?.classList.add('radar-map-sheet');$('.sheetcontent')?.insertAdjacentHTML('afterbegin',`<div class="radar-map-toolbar"><button class="secondary" onclick="planJourney()">${ic('search')} Search journey</button><span class="signal">${ic('clock')}40 min · demo</span><button class="textbtn" onclick="closeModal()">Done</button></div>`)};
setInterval(()=>{if(document.hidden||!radarRunning||arrivalMode!=='preview')return;arrivalTime+=1/60;let sheet=$('#sheet-diagram');if(sheet){let view=sheet._captureView?.();sheet.innerHTML=networkSvg();installDiagram(sheet);if(view)sheet._restoreView?.(view)}else if(!$('.sheet')&&!['SELECT','INPUT'].includes(document.activeElement?.tagName))render()},1000);
render();
